from pysat.solvers import Glucose3, Cadical153, Minisat22
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
n_cliques=3;k=4;n=12;M=26
edges=[]
for g in range(n_cliques):
 for i in range(k):
  for j in range(i+1,k): edges.append((g*k+i,g*k+j))
for g in range(n_cliques-1):
 for i in range(k): edges.append((g*k+i,(g+1)*k+i))
print(len(edges))
vpool=IDPool()
def X(v,l): return vpool.id(('x',v,l))
def Y(e,d): return vpool.id(('y',e,d))
clauses=[]
# vertex exactly one label
for v in range(n):
 lits=[X(v,l) for l in range(M+1)]
 clauses.append(lits)
 clauses += CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses
# label at most one vertex
for l in range(M+1):
 lits=[X(v,l) for v in range(n)]
 clauses += CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses
# edge exactly one diff
for e,(u,v) in enumerate(edges):
 lits=[Y(e,d) for d in range(1,M+1)]
 clauses.append(lits)
 clauses += CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses
 # if labels assigned imply diff
 for a in range(M+1):
  for b in range(M+1):
   if a==b: continue # uniqueness global disallows same but endpoints labels distinct
   d=abs(a-b)
   clauses.append([-X(u,a), -X(v,b), Y(e,d)])
 # if y_e_d then forbid incompatible pairs. Instead because exactly one y and label->y suffices? Yes if labels imply Y(d), exactly one y, so chosen y must actual. no need reverse.
# diff at most one edge
for d in range(1,M+1):
 lits=[Y(e,d) for e in range(len(edges))]
 clauses += CardEnc.atmost(lits, bound=1, vpool=vpool, encoding=EncType.seqcounter).clauses
# symmetry complement L0 <= 13 (optional) labels 14..26 false for vertex0
for l in range(14,M+1): clauses.append([-X(0,l)])
print('vars',vpool.top,'clauses',len(clauses))
for Solver in [Cadical153, Glucose3, Minisat22]:
 try:
  print('solver',Solver)
  with Solver(bootstrap_with=clauses) as s:
   sat=s.solve()
   print('sat',sat)
   if sat:
    model=set(s.get_model())
    sol=[]
    for v in range(n):
     lab=[l for l in range(M+1) if X(v,l) in model]
     sol.append(lab[0])
    print(sol)
    diffs=[abs(sol[u]-sol[v]) for u,v in edges]
    print(sorted(diffs),len(set(diffs)))
    print(list(zip(range(len(edges)),edges,diffs)))
    break
 except Exception as e:
  print('err',e)
